import os, re, json, csv, zlib, email
from email import policy
from bs4 import BeautifulSoup
import xml.etree.ElementTree as ET
import openpyxl

ROOT = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_11"

def pdf_text(path):
    raw = open(path, "rb").read()
    out = []
    for m in re.finditer(rb"stream\r?\n(.*?)\r?\nendstream", raw, re.S):
        data = m.group(1)
        try: data = zlib.decompress(data)
        except Exception: pass
        for tm in re.finditer(rb"\((?:[^()\\]|\\.)*\)", data):
            s = tm.group(0)[1:-1].replace(b"\\(", b"(").replace(b"\\)", b")").replace(b"\\\\", b"\\")
            out.append(s.decode("utf-8","replace"))
    return re.sub(r"\s+", " ", " ".join(out))

def html_text(path):
    soup = BeautifulSoup(open(path, encoding="utf-8").read(), "html.parser")
    for t in soup(["script","style"]): t.decompose()
    return re.sub(r"[ \t]+", " ", soup.get_text("\n"))

def eml_text(path):
    msg = email.message_from_binary_file(open(path,"rb"), policy=policy.default)
    parts = []
    for h in ["From","To","Subject","Date"]:
        if msg[h]: parts.append(f"{h}: {msg[h]}")
    body = msg.get_body(preferencelist=("plain","html"))
    if body: parts.append(body.get_content())
    return re.sub(r"[ \t]+", " ", "\n".join(parts))

def xml_text(path):
    tree = ET.parse(path)
    parts = []
    def walk(el):
        if el.text and el.text.strip(): parts.append(el.text.strip())
        for c in el: walk(c)
        if el.tail and el.tail.strip(): parts.append(el.tail.strip())
    walk(tree.getroot())
    return "\n".join(parts)

def get_text(path):
    ext = path.rsplit(".",1)[-1].lower()
    if ext == "pdf": return pdf_text(path)
    if ext == "html": return html_text(path)
    if ext == "eml": return eml_text(path)
    if ext == "xml": return xml_text(path)
    return open(path, encoding="utf-8").read()

FIELD_LABELS = {
    "record_id": r"Record:\s*", "portfolio_key": r"Portfolio key:\s*",
    "source_system": r"Source system:\s*", "evidence_role": r"Evidence role:\s*",
    "immutable_entity": r"Immutable entity:\s*", "referenced_revision": r"Referenced revision:\s*",
    "current_revision": r"Current revision:\s*", "custodian": r"Custodian:\s*", "reviewer": r"Reviewer:\s*",
}
def grab(text, name):
    # matches "Label: value" or "| Label | value |" or "Label: value" across newlines
    pats = [
        rf"\|\s*{name.replace('_',' ')}\s*\|\s*([^|\n]+)",
        rf"{name.replace('_',' ').capitalize()}:\s*([^\n|]+)",
    ]
    for p in pats:
        m = re.search(p, text, re.I)
        if m: return m.group(1).strip()
    return None

def extract_native_record(text):
    # md: "## Native record\n\n<body>" ; pdf/txt: "NATIVE RECORD <body> SOURCE LINEAGE"
    m = re.search(r"##\s*Native record\s*\n+(.*?)\n\s*##", text, re.S)
    if m: return re.sub(r"\s+"," ", m.group(1)).strip()
    m = re.search(r"NATIVE RECORD\s+(.*?)\s+(?:SOURCE LINEAGE|BUSINESS CONTEXT)", text, re.S)
    if m: return re.sub(r"\s+"," ", m.group(1)).strip()
    return None

records = []
for dirpath, _, files in os.walk(ROOT):
    for fn in sorted(files):
        path = os.path.join(dirpath, fn)
        rel = os.path.relpath(path, ROOT)
        if fn.endswith(".xlsx"):
            records.append({"file": rel, "format": "xlsx"})
