        for f in ["record_id","portfolio_key","source_system","evidence_role","immutable_entity","referenced_revision","current_revision","custodian","reviewer"]:
            rec[f] = grab(text, f)
        rec["native_record"] = extract_native_record(text)
        records.append(rec)

# JSON: use direct fields
for r in records:
    if r["format"] == "json":
        d = json.load(open(os.path.join(ROOT, r["file"]), encoding="utf-8"))
        for k in ["record_id","portfolio_key","source_system","evidence_role","immutable_entity_key","referenced_revision","current_revision","custodian","reviewer","body","subject","counterparty"]:
            key = "immutable_entity" if k=="immutable_entity_key" else k
            if k in d: r[key] = d[k]

# CSV: metadata rows
for r in records:
    if r["format"] == "csv":
        with open(os.path.join(ROOT, r["file"]), encoding="utf-8") as f:
            for row in csv.DictReader(f):
                if row.get("row_type") == "metadata":
                    k = row["key"]
                    v = row["value"]
                    if k == "immutable_entity_key": k = "immutable_entity"
