    if m: return re.sub(r"\s+"," ", m.group(1)).strip()
    m = re.search(r"NATIVE RECORD\s+(.*?)\s+(?:SOURCE LINEAGE|BUSINESS CONTEXT|RELIANCE)", text, re.S|re.I)
    if m: return re.sub(r"\s+"," ", m.group(1)).strip()
