import re, json
from collections import defaultdict
records = json.load(open("/tmp/records.json"))
by_key = defaultdict(list)
for r in records:
    if r["fmt"] == "xlsx": continue
    by_key[r["portfolio_key"]].append(r)

def classify(rs):
    out = {}
    for r in rs:
        n = r["native"] or ""
        if "Crosswalk revision" in n or "is associated with both" in n: out.setdefault("identity", r)
        elif "matter-level control is" in n: out.setdefault("operative", r)
        elif "operating extract" in n: out.setdefault("currops", r)
        elif "responsibility roster" in n: out.setdefault("approval", r)
    return out

SUP = ['CBP-061-01','CBP-061-02','CBP-061-03','CBP-061-04','CBP-061-05','CBP-061-06','CBP-061-10','CBP-061-12']
for k in sorted(by_key, key=lambda x: int(x.split("-")[-1])):
    c = classify(by_key[k])
    oper, cops = c.get("operative"), c.get("currops")
    oref = re.search(r"CB-PR-3001-(R\d+)", oper["native"]).group(1) if oper and re.search(r"CB-PR-3001-(R\d+)", oper["native"]) else None
    eref = re.search(r"CB-PR-3001-(E\d+)", cops["native"]).group(1) if cops and re.search(r"CB-PR-3001-(E\d+)", cops["native"]) else None
    orev = re.search(r"both (REV-\d{4}\.\d+)", oper["native"]).group(1) if oper and re.search(r"both (REV-\d{4}\.\d+)", oper["native"]) else None
    if oper and not orev:
        m = re.search(r"(REV-\d{4}\.\d+) is the later effective revision", oper["native"])
        orev = m.group(1) if m else None
    # subject from identity native
    ident = c.get("identity")
    subj = None
    if ident:
        m = re.search(r"legal name Arcadia Genomics, Inc. — (.+?) record \d+", ident["native"])
        if m: subj = m.group(1)
    print(f"{k} | subj={subj} | operative={oper['record_id'] if oper else None} {oref} rev={orev} | currops={cops['record_id'] if cops else None} {eref} | {'SUP' if k in SUP else 'HOLD'}")

